async function setup(){const f=await ministryFixture();fixtures.push(f);const call=(p:string,b?:unknown)=>handleTripAdminRequest(f.request(p,b),f.env,p);const opportunity=f.sqlite.prepare("SELECT id FROM opportunities WHERE kind='trip' LIMIT 1").get()!.id;
 const response=await call('/admin/trips',{title:'Vetting departure',location:'England',startDate:'2027-07-10',endDate:'2027-07-17',opportunityId:opportunity});const {id}=await response.json() as any;
 const ids=['Alice','Ben'].map(name=>{const p=crypto.randomUUID();f.sqlite.prepare("INSERT INTO people(id,first_name,last_name,first_name_normalized,last_name_normalized,email,email_normalized,created_at,updated_at) VALUES(?,?,'Example',?,'example',?,?,'now','now')").run(p,name,name.toLowerCase(),name+'@example.test',name.toLowerCase()+'@example.test');f.sqlite.prepare("INSERT INTO contact_types VALUES(?,'prospective_traveler','now')").run(p);f.sqlite.prepare("INSERT INTO contact_trips VALUES(?,?,'now')").run(p,opportunity);return p;});const base='/admin/trips/'+id+'/vetting',board=async()=>{const r=await call(base);expect(r.status,await r.clone().text()).toBe(200);return (await r.json() as any).travelers;};const batch=async(action:string,extra={})=>call(base,{action,...extra,people:(await board()).map((p:any)=>({personId:p.person_id,revision:p.revision}))});return {...f,call,id,ids,base,board,batch};}
const applicationSessions=new WeakMap<object,Map<string,string>>();
async function applicationCall(f:{env:any},token:string,body?:unknown){
 const raw=(key:string,value?:unknown)=>handleTravelerVetting(new Request('http://localhost/api/interest/public/traveler-application',{method:value?'POST':'GET',headers:{'Content-Type':'application/json','X-Application-Token':key},body:value?JSON.stringify(value):undefined}),f.env,'/public/traveler-application');
 let sessions=applicationSessions.get(f.env);if(!sessions){sessions=new Map();applicationSessions.set(f.env,sessions);}let session=sessions.get(token);
 if(!session){const opened=await raw(token);if(!opened.ok)return opened;const data=await opened.clone().json() as any;session=data.sessionToken;sessions.set(token,session!);if(!body)return opened;}
 return raw(session!,body);
}
async function sendApplicationInvitations(f:any,payload:any){
 if(!payload.previewId){const response=await f.call(f.base+'/application-preview',payload);if(!response.ok)return response;const preview=await response.clone().json();if(!preview.recipients.length)return response;payload.previewId=preview.previewId;}
 return f.call(f.base+'/application-emails',payload);
}
