it('requires a signature and rejects unresolved screening delivery replacements',async()=>{const f=await setup();Object.assign(f.env,{ENVIRONMENT:'test'});await f.batch('background',{backgroundStatus:'in_progress'});const payload={url:'https://vendor.example.test/form',explanation:'Please complete the screening form for this children’s ministry trip.',sendId:crypto.randomUUID(),people:(await f.board()).map((p:any)=>({personId:p.person_id,revision:p.revision}))};expect((await f.call(f.base+'/screening-preview',payload)).status).toBe(503);f.files.set(signatureKey,new Uint8Array([1,2,3]));expect((await f.call(f.base+'/screening-emails',payload)).status).toBe(200);const email=f.sqlite.prepare('SELECT id FROM traveler_screening_emails LIMIT 1').get()!;f.sqlite.prepare("UPDATE traveler_screening_emails SET status='uncertain',started_at='2026-01-01',updated_at='2026-01-01' WHERE id=?").run(email.id);expect((await f.call(f.base+'/screening-retry',{emailId:email.id})).status).toBe(409);expect((await f.call(f.base+'/screening-emails',{...payload,sendId:crypto.randomUUID(),people:(await f.board()).map((p:any)=>({personId:p.person_id,revision:p.revision}))})).status).toBe(409);});
