it('uses expiring, replaceable private links, validates answers and preserves contact data until review',async()=>{const f=await setup(),p=f.ids[0];let response=await f.call(f.base+'/'+p+'/invite',{revision:-1});expect(response.status,await response.clone().text()).toBe(200);const first=(await response.json() as any).path.split('#')[1];response=await f.call(f.base+'/'+p+'/invite',{revision:0});const token=(await response.json() as any).path.split('#')[1];const publicCall=(t:string,body?:unknown)=>applicationCall(f,t,body);expect((await publicCall(first)).status).toBe(404);expect(await (await publicCall(token)).json()).toMatchObject({tripTitle:'Vetting departure',firstName:'Alice',submitted:false,profile:{legalName:'Alice Example'}});expect((await publicCall(token,{details:{...answers,birthdate:'2026-02-30'},consent:true})).status).toBe(422);expect((await publicCall(token,{details:answers,consent:false})).status).toBe(422);expect((await publicCall(token,{details:answers,consent:true})).status).toBe(200);expect((await publicCall(token,{details:answers,consent:true})).status).toBe(200);const detail=await f.call(f.base+'/'+p);expect(detail.status,await detail.clone().text()).toBe(200);const d=await detail.json() as any;expect(d.profile).toEqual({legalName:'Alice Example'});expect(d.applications.find((a:any)=>a.status==='submitted').answers.birthdate).toBe(answers.birthdate);expect((await f.board()).find((r:any)=>r.person_id===p)).toMatchObject({stage:'review',application_status:'submitted'});const path='/admin/traveler-profiles/'+p;response=await handleTravelerVetting(f.request(path,{details:answers,revision:-1}),f.env,path);expect(response.status).toBe(200);expect((await handleTravelerVetting(f.request(path,{details:answers,revision:-1}),f.env,path)).status).toBe(409);});
